/** What the tools actually do, inside the sandbox, confined to the repository. */
import { execFile } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";

import type { ToolCall } from "./protocol.ts";

export interface ToolResult {
  ok: boolean;
  output: string;
}

/** Results are fed back to a model with a 4,096-token window, so keep them short. */
export const OUTPUT_LIMIT = 1500;
const SHELL_TIMEOUT_MS = 30_000;

export function clip(text: string, limit = OUTPUT_LIMIT): string {
  return text.length <= limit ? text : `${text.slice(0, limit)}\n[cut: ${text.length} characters in total]`;
}

/** The absolute path, or null if it would land outside the repository. */
export function insideRepo(repoDir: string, path: string): string | null {
  const root = resolve(repoDir);
  const target = resolve(root, path);
  return target === root || target.startsWith(root + sep) ? target : null;
}

function run(file: string, args: string[], cwd: string): Promise<{ code: number; stdout: string; stderr: string }> {
  return new Promise((done) => {
    execFile(file, args, { cwd, timeout: SHELL_TIMEOUT_MS, maxBuffer: 1024 * 1024 }, (error, stdout, stderr) => {
      const code = error ? (typeof error.code === "number" ? error.code : 1) : 0;
      done({ code, stdout, stderr: error?.killed ? `${stderr}\n[stopped after ${SHELL_TIMEOUT_MS / 1000} s]` : stderr });
    });
  });
}

export async function runTool(call: ToolCall, repoDir: string): Promise<ToolResult> {
  const { tool, args } = call;
  try {
    if (["read_file", "write_file", "append_file", "replace_in_file"].includes(tool)) {
      const path = insideRepo(repoDir, args.path);
      if (!path) return { ok: false, output: `ERROR: ${args.path} is outside the repository` };
      if (tool === "read_file") return { ok: true, output: clip(await readFile(path, "utf8")) };
      if (tool === "write_file") {
        await mkdir(dirname(path), { recursive: true });
        await writeFile(path, args.content);
        return { ok: true, output: `Wrote ${args.content.length} characters to ${args.path}` };
      }
      const before = await readFile(path, "utf8");
      if (tool === "append_file") {
        // Start on a fresh line, and leave the file ending with one.
        const joiner = before === "" || before.endsWith("\n") ? "" : "\n";
        const ending = args.content.endsWith("\n") ? "" : "\n";
        await writeFile(path, before + joiner + args.content + ending);
        return { ok: true, output: `Added ${args.content.length} characters to the end of ${args.path}` };
      }
      const matches = before.split(args.find).length - 1;
      if (!args.find || matches === 0) {
        return { ok: false, output: `ERROR: that text was not found in ${args.path}. Read the file and copy the text exactly.` };
      }
      await writeFile(path, before.replace(args.find, () => args.replace));
      const extra = matches > 1 ? ` (it appears ${matches} times; only the first was changed)` : "";
      return { ok: true, output: `Replaced the text in ${args.path}${extra}` };
    }
    if (tool === "search_files") {
      const found = await run("rg", ["--line-number", "--max-count", "5", "--max-columns", "200", "--", args.pattern, "."], repoDir);
      if (found.code === 1) return { ok: true, output: "No matches." };
      if (found.code !== 0) return { ok: false, output: clip(`ERROR: ${found.stderr.trim()}`) };
      return { ok: true, output: clip(found.stdout) };
    }
    if (tool === "run_shell") {
      const result = await run("sh", ["-c", args.command], repoDir);
      const text = [`exit code ${result.code}`, result.stdout.trim(), result.stderr.trim()].filter(Boolean).join("\n");
      return { ok: result.code === 0, output: clip(text) };
    }
    return { ok: false, output: `ERROR: unknown tool ${tool}` };
  } catch (error) {
    return { ok: false, output: clip(`ERROR: ${error instanceof Error ? error.message : String(error)}`) };
  }
}

/** Starts the API with a real database and real sandboxes.  node api/main.ts */
import { loadConfig } from "../config.ts";
import { Db } from "../db/index.ts";
import { executeRun } from "../orchestrator/run.ts";
import { ModalSandboxProvider } from "../sandbox-provider/modal.ts";
import { createApi } from "./server.ts";

process.loadEnvFile(".env");
const config = loadConfig();
const db = new Db(config.dbPath);
const sandboxes = new ModalSandboxProvider();

const api = createApi({
  db,
  ownerToken: config.ownerToken,
  // One run at a time is the v1 rule; runs started together simply overlap for now.
  startRun: (runId) => void executeRun({ db, sandboxes, config }, runId),
});

api.listen(config.port, () => console.log(`AgentDash API listening on http://localhost:${config.port}`));

/**
 * Outside HTTP world ↔ the system.
 *
 * Reading is open to anyone (decision 16); starting and killing runs needs
 * the owner's token. Plain node:http, no framework.
 */
import { randomBytes, timingSafeEqual } from "node:crypto";
import { createServer } from "node:http";
import type { IncomingMessage, Server, ServerResponse } from "node:http";

import type { Db } from "../db/index.ts";
import { isTerminal } from "../orchestrator/state.ts";

/** Only public GitHub repositories over HTTPS, so a sandbox never needs credentials. */
const REPO_URL = /^https:\/\/github\.com\/[\w.-]+\/[\w.-]+?(\.git)?$/;
const MAX_TASK_LENGTH = 4000;
const MAX_BODY_BYTES = 64 * 1024;

export interface ApiDeps {
  db: Db;
  ownerToken: string;
  /** Hands a newly created run to the orchestrator. Must not block. */
  startRun: (runId: string) => void;
}

export function validateNewRun(body: unknown): { task: string; repoUrl: string } | string {
  if (typeof body !== "object" || body === null) return "body must be a JSON object";
  const { task, repoUrl } = body as Record<string, unknown>;
  if (typeof task !== "string" || !task.trim()) return "task must be a non-empty string";
  if (task.length > MAX_TASK_LENGTH) return `task must be at most ${MAX_TASK_LENGTH} characters`;
  if (typeof repoUrl !== "string" || !REPO_URL.test(repoUrl)) {
    return "repoUrl must be a public GitHub repository, like https://github.com/owner/name";
  }
  return { task: task.trim(), repoUrl };
}

function isOwner(request: IncomingMessage, ownerToken: string): boolean {
  const given = Buffer.from((request.headers.authorization ?? "").replace(/^Bearer /, ""));
  const expected = Buffer.from(ownerToken);
  return given.length === expected.length && timingSafeEqual(given, expected);
}

async function readJson(request: IncomingMessage): Promise<unknown> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new Error("body too large");
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString("utf8") || "null");
}

function send(response: ServerResponse, status: number, body: unknown): void {
  response.writeHead(status, { "content-type": "application/json" });
  response.end(JSON.stringify(body));
}

export function createApi(deps: ApiDeps): Server {
  const { db, ownerToken, startRun } = deps;

  return createServer(async (request, response) => {
    try {
      const url = new URL(request.url ?? "/", "http://localhost");
      const [, root, runId, action] = url.pathname.split("/");
      const method = request.method ?? "GET";

      if (method === "GET" && url.pathname === "/health") return send(response, 200, { ok: true });
      if (root !== "runs") return send(response, 404, { error: "not found" });

      if (!runId) {
        if (method === "GET") return send(response, 200, { runs: db.listRuns() });
        if (method === "POST") {
          if (!isOwner(request, ownerToken)) return send(response, 401, { error: "unauthorised" });
          let body: unknown;
          try {
            body = await readJson(request);
          } catch {
            return send(response, 400, { error: "body is not valid JSON" });
          }
          const valid = validateNewRun(body);
          if (typeof valid === "string") return send(response, 400, { error: valid });
          const run = db.createRun({ id: `run_${randomBytes(6).toString("hex")}`, ...valid });
          db.appendEvent(run.id, "status", { status: "queued" });
          startRun(run.id);
          return send(response, 201, { run });
        }
        return send(response, 405, { error: "method not allowed" });
      }

      const run = db.getRun(runId);
      if (!run) return send(response, 404, { error: "no such run" });

      if (method === "GET" && !action) {
        return send(response, 200, { run, assignments: db.listAssignments(runId) });
      }
      if (method === "GET" && action === "events") {
        const after = Number(url.searchParams.get("after") ?? 0) || 0;
        return send(response, 200, { events: db.listEvents(runId, after) });
      }
      if (method === "POST" && action === "kill") {
        if (!isOwner(request, ownerToken)) return send(response, 401, { error: "unauthorised" });
        if (isTerminal(run.status)) return send(response, 409, { error: `run already ${run.status}` });
        db.requestKill(runId);
        db.appendEvent(runId, "kill_requested", {});
        return send(response, 202, { ok: true });
      }
      return send(response, 404, { error: "not found" });
    } catch (error) {
      send(response, 500, { error: error instanceof Error ? error.message : "internal error" });
    }
  });
}

/** Environment ↔ application. Everything configurable is read here, once. */

export interface Config {
  gatewayUrl: string;
  /** Owner key for the gateway. Also the secret that signs per-run tokens. */
  gatewayKey: string;
  /** Required to start or kill runs through the API. */
  ownerToken: string;
  dbPath: string;
  port: number;
  /** How long a run's gateway pass stays valid. */
  runTokenTtlSeconds: number;
  /** Modal destroys a run's sandbox after this long even if we never do. */
  sandboxMaxLifetimeSeconds: number;
  /** The agent is stopped after this many model calls. */
  agentMaxSteps: number;
  /** The agent is stopped after this long, whatever it is doing. */
  agentTimeoutSeconds: number;
}

const REQUIRED = ["GATEWAY_URL", "GATEWAY_KEY", "OWNER_TOKEN"] as const;

export function loadConfig(env: Record<string, string | undefined> = process.env): Config {
  const missing = REQUIRED.filter((name) => !env[name]);
  if (missing.length) throw new Error(`Missing environment variables: ${missing.join(", ")}`);
  return {
    gatewayUrl: env.GATEWAY_URL!.replace(/\/$/, ""),
    gatewayKey: env.GATEWAY_KEY!,
    ownerToken: env.OWNER_TOKEN!,
    dbPath: env.DB_PATH ?? "agentdash.db",
    port: Number(env.PORT ?? 8787),
    runTokenTtlSeconds: Number(env.RUN_TOKEN_TTL_SECONDS ?? 900),
    sandboxMaxLifetimeSeconds: Number(env.SANDBOX_MAX_LIFETIME_SECONDS ?? 600),
    agentMaxSteps: Number(env.AGENT_MAX_STEPS ?? 8),
    agentTimeoutSeconds: Number(env.AGENT_TIMEOUT_SECONDS ?? 300),
  };
}

/**
 * Application ↔ persistent state.
 *
 * SQLite through Node's built-in driver: a single file, no account and no
 * cost. Callers use only the functions below, so moving to hosted Postgres at
 * deploy time means rewriting this file and nothing else.
 */
import { DatabaseSync } from "node:sqlite";

import { assertTransition } from "../orchestrator/state.ts";
import type { RunStatus } from "../orchestrator/state.ts";

const SCHEMA = `
CREATE TABLE IF NOT EXISTS runs (
  id TEXT PRIMARY KEY,
  task TEXT NOT NULL,
  repo_url TEXT NOT NULL,
  status TEXT NOT NULL,
  kill_requested INTEGER NOT NULL DEFAULT 0,
  patch TEXT,
  error TEXT,
  sandbox_seconds REAL,
  sandbox_cost_usd REAL,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS events (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id TEXT NOT NULL REFERENCES runs(id),
  at TEXT NOT NULL,
  type TEXT NOT NULL,
  data TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS events_by_run ON events(run_id, id);
CREATE TABLE IF NOT EXISTS model_assignments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run_id TEXT NOT NULL REFERENCES runs(id),
  at TEXT NOT NULL,
  tier TEXT NOT NULL,
  decided_by TEXT NOT NULL,
  reason TEXT NOT NULL
);
`;

export interface Run {
  id: string;
  task: string;
  repoUrl: string;
  status: RunStatus;
  killRequested: boolean;
  patch: string | null;
  error: string | null;
  sandboxSeconds: number | null;
  sandboxCostUsd: number | null;
  createdAt: string;
  updatedAt: string;
}

export interface RunEvent {
  id: number;
  runId: string;
  at: string;
  type: string;
  data: Record<string, unknown>;
}

export interface ModelAssignment {
  runId: string;
  at: string;
  tier: string;
  decidedBy: string;
  reason: string;
}

type Row = Record<string, any>;

const toRun = (row: Row): Run => ({
  id: row.id,
  task: row.task,
  repoUrl: row.repo_url,
  status: row.status,
  killRequested: row.kill_requested === 1,
  patch: row.patch,
  error: row.error,
  sandboxSeconds: row.sandbox_seconds,
  sandboxCostUsd: row.sandbox_cost_usd,
  createdAt: row.created_at,
  updatedAt: row.updated_at,
});

const toEvent = (row: Row): RunEvent => ({
  id: row.id,
  runId: row.run_id,
  at: row.at,
  type: row.type,
  data: JSON.parse(row.data),
});

export class Db {
  readonly #db: DatabaseSync;
  readonly #now: () => Date;

  constructor(path: string, now: () => Date = () => new Date()) {
    this.#db = new DatabaseSync(path);
    this.#db.exec(SCHEMA);
    this.#now = now;
  }

  #stamp(): string {
    return this.#now().toISOString();
  }

  createRun(run: { id: string; task: string; repoUrl: string }): Run {
    const at = this.#stamp();
    this.#db
      .prepare("INSERT INTO runs (id, task, repo_url, status, created_at, updated_at) VALUES (?, ?, ?, 'queued', ?, ?)")
      .run(run.id, run.task, run.repoUrl, at, at);
    return this.getRun(run.id)!;
  }

  getRun(id: string): Run | null {
    const row = this.#db.prepare("SELECT * FROM runs WHERE id = ?").get(id);
    return row ? toRun(row) : null;
  }

  listRuns(limit = 50): Run[] {
    return this.#db.prepare("SELECT * FROM runs ORDER BY created_at DESC LIMIT ?").all(limit).map(toRun);
  }

  /** Move a run to a new status, refusing moves the lifecycle does not allow. */
  setStatus(id: string, to: RunStatus, error?: string): Run {
    const run = this.getRun(id);
    if (!run) throw new Error(`No run ${id}`);
    assertTransition(run.status, to);
    this.#db
      .prepare("UPDATE runs SET status = ?, error = COALESCE(?, error), updated_at = ? WHERE id = ?")
      .run(to, error ?? null, this.#stamp(), id);
    return this.getRun(id)!;
  }

  requestKill(id: string): void {
    this.#db.prepare("UPDATE runs SET kill_requested = 1, updated_at = ? WHERE id = ?").run(this.#stamp(), id);
  }

  savePatch(id: string, patch: string): void {
    this.#db.prepare("UPDATE runs SET patch = ?, updated_at = ? WHERE id = ?").run(patch, this.#stamp(), id);
  }

  saveSandboxUsage(id: string, seconds: number, costUsd: number): void {
    this.#db
      .prepare("UPDATE runs SET sandbox_seconds = ?, sandbox_cost_usd = ?, updated_at = ? WHERE id = ?")
      .run(seconds, costUsd, this.#stamp(), id);
  }

  appendEvent(runId: string, type: string, data: Record<string, unknown> = {}): RunEvent {
    const at = this.#stamp();
    const result = this.#db
      .prepare("INSERT INTO events (run_id, at, type, data) VALUES (?, ?, ?, ?)")
      .run(runId, at, type, JSON.stringify(data));
    return { id: Number(result.lastInsertRowid), runId, at, type, data };
  }

  /** Events for a run in order; pass the last id seen to get only newer ones. */
  listEvents(runId: string, afterId = 0): RunEvent[] {
    return this.#db
      .prepare("SELECT * FROM events WHERE run_id = ? AND id > ? ORDER BY id")
      .all(runId, afterId)
      .map(toEvent);
  }

  addAssignment(runId: string, assignment: { tier: string; decidedBy: string; reason: string }): void {
    this.#db
      .prepare("INSERT INTO model_assignments (run_id, at, tier, decided_by, reason) VALUES (?, ?, ?, ?, ?)")
      .run(runId, this.#stamp(), assignment.tier, assignment.decidedBy, assignment.reason);
  }

  listAssignments(runId: string): ModelAssignment[] {
    return this.#db
      .prepare("SELECT * FROM model_assignments WHERE run_id = ? ORDER BY id")
      .all(runId)
      .map((row: Row) => ({
        runId: row.run_id,
        at: row.at,
        tier: row.tier,
        decidedBy: row.decided_by,
        reason: row.reason,
      }));
  }

  close(): void {
    this.#db.close();
  }
}

"""The gateway: the one public door to the models.

Deploy with:  py -m modal deploy gateway/main.py   (after model-server/serve.py)

Every model request comes through here. The gateway checks the caller's key,
refuses once the month's budget is spent, forwards to the model service,
and writes one ledger line per call. The rules live in core.py; this file is
only the web and Modal wiring.
"""

import asyncio
import hmac
import json
import os
import time
from datetime import datetime, timezone
from pathlib import Path

import modal

import core

MODEL_APP = "agentdash-model"
LEDGER_DIR = Path("/ledger")

image = (
    modal.Image.debian_slim(python_version="3.12")
    .pip_install("fastapi[standard]")
    .add_local_python_source("core")
)

# One JSON-lines file per month. Stands in for the database until step 3.
ledger_volume = modal.Volume.from_name("agentdash-ledger", create_if_missing=True)

app = modal.App("agentdash-gateway")


def read_ledger(month: str) -> list[dict]:
    path = LEDGER_DIR / f"{month}.jsonl"
    if not path.exists():
        return []
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def append_ledger(month: str, record: dict) -> None:
    with open(LEDGER_DIR / f"{month}.jsonl", "a") as file:
        file.write(json.dumps(record) + "\n")


@app.function(
    image=image,
    secrets=[modal.Secret.from_name("agentdash-gateway")],
    volumes={str(LEDGER_DIR): ledger_volume},
    cpu=0.25,
    memory=256,
    timeout=600,
    scaledown_window=60,
    # A single container, so the lock below really does serialise budget checks.
    max_containers=1,
)
@modal.concurrent(max_inputs=20)
@modal.asgi_app()
def web():
    from fastapi import FastAPI, Request
    from fastapi.responses import JSONResponse

    api = FastAPI(title="AgentDash gateway")
    model = modal.Cls.from_name(MODEL_APP, "Model")()
    # Held from budget check to ledger write, so two calls cannot both pass the
    # check on the last cent. The model handles one request at a time anyway.
    lock = asyncio.Lock()
    # Modal's own metered cost for the month: the truth the hard stop is checked
    # against. It covers everything in the workspace, not just model calls.
    vendor = {"usd": None, "at": 0.0, "error": None}

    async def vendor_spend() -> float | None:
        if time.time() - vendor["at"] < 60:
            return vendor["usd"]
        try:
            summary = await asyncio.to_thread(
                lambda: modal.Workspace.from_context().billing.summary(cycle="this month")
            )
            vendor["usd"] = max(
                float(summary.metered_cost), float(sum(summary.metered_cost_breakdown.values()))
            )
            vendor["error"] = None
        except Exception as error:  # keep the last known figure and fall back to the ledger
            vendor["error"] = str(error)[:200]
        vendor["at"] = time.time()
        return vendor["usd"]

    def authorised(request: Request) -> bool:
        expected = os.environ["GATEWAY_KEY"]
        supplied = request.headers.get("authorization", "").removeprefix("Bearer ").strip()
        return hmac.compare_digest(supplied.encode(), expected.encode())

    def run_from_pass(request: Request) -> str | None:
        """The run id if the caller holds a valid per-run pass."""
        supplied = request.headers.get("authorization", "").removeprefix("Bearer ").strip()
        return core.verify_run_token(os.environ["GATEWAY_KEY"], supplied, time.time())

    def denied():
        return JSONResponse({"error": "unauthorised"}, status_code=401)

    @api.get("/health")
    async def health():
        return {"ok": True}

    @api.get("/v1/models")
    async def models(request: Request):
        if not authorised(request):
            return denied()
        return {"models": [entry.public() for entry in core.REGISTRY.values()]}

    @api.get("/v1/usage")
    async def usage(request: Request):
        if not authorised(request):
            return denied()
        month = core.month_key(datetime.now(timezone.utc))
        records = read_ledger(month)
        return {
            "month": month,
            "budget": core.budget_view(core.total_spent(records), await vendor_spend()),
            "vendor_meter_error": vendor["error"],
            "summary": core.summarise(records),
            "recent": records[-20:],
        }

    @api.post("/v1/chat")
    async def chat(request: Request):
        # The owner key may call as any role. A per-run pass, which is all a
        # sandbox holds, may only call as that run's worker.
        pass_run_id = None if authorised(request) else run_from_pass(request)
        if not authorised(request) and pass_run_id is None:
            return denied()
        try:
            body = await request.json()
        except ValueError:
            return JSONResponse({"error": "body is not valid JSON"}, status_code=400)
        clean, problem = core.validate_chat_request(body)
        if problem:
            return JSONResponse({"error": problem}, status_code=400)
        if pass_run_id is not None:
            clean["run_id"] = pass_run_id
            clean["role"] = "worker"
        entry = core.REGISTRY[clean["tier"]]

        async with lock:
            now = datetime.now(timezone.utc)
            month = core.month_key(now)
            records = read_ledger(month)
            ledger_usd = core.total_spent(records)
            vendor_usd = await vendor_spend()
            budget = core.budget_view(ledger_usd, vendor_usd)
            if budget["exhausted"]:
                return JSONResponse({"error": "budget_exhausted", "budget": budget}, status_code=402)

            idle = core.idle_seconds(
                core.last_end(records, entry.tier),
                time.time(),
                entry.idle_window_seconds,
                entry.wake_overhead_seconds,
            )
            # Timed from here, so a cold start or a wait in the queue is billed too.
            started = time.monotonic()
            try:
                reply = await model.chat.remote.aio(
                    entry.model,
                    clean["messages"],
                    clean["tools"],
                    {
                        "num_predict": clean["max_tokens"],
                        "temperature": clean["temperature"],
                        "num_thread": entry.num_threads,
                    },
                    clean["response_format"],
                )
            except Exception as error:  # the machine failed, timed out, or is not deployed
                reply = {"error": f"model service failed: {error}"}
            billed_seconds = time.monotonic() - started

            record = core.make_record(
                at=now,
                request=clean,
                entry=entry,
                billed_seconds=billed_seconds,
                idle=idle,
                ended_at=time.time(),
                reply=reply,
            )
            append_ledger(month, record)
            await ledger_volume.commit.aio()
            budget = core.budget_view(ledger_usd + record["cost_usd"], vendor_usd)

        usage_out = {
            key: record[key]
            for key in (
                "prompt_tokens",
                "output_tokens",
                "model_seconds",
                "billed_seconds",
                "idle_seconds",
                "cost_usd",
                "hardware",
            )
        }
        if reply.get("error"):
            return JSONResponse(
                {"error": reply["error"], "usage": usage_out, "budget": budget}, status_code=502
            )
        return {
            "tier": entry.tier,
            "model": entry.model,
            "message": reply.get("message", {}),
            "usage": usage_out,
            "budget": budget,
        }

    return api

"""Send one prompt through the deployed gateway, or show the month's usage.

    py gateway/try_it.py "Write a haiku about queues"
    py gateway/try_it.py --usage

Reads GATEWAY_URL and GATEWAY_KEY from the .env file in the project root.
"""

import json
import sys
import urllib.error
import urllib.request
from pathlib import Path


def load_env() -> dict:
    env = {}
    for line in (Path(__file__).resolve().parent.parent / ".env").read_text().splitlines():
        if "=" in line and not line.lstrip().startswith("#"):
            key, value = line.split("=", 1)
            env[key.strip()] = value.strip()
    return env


def call(env: dict, path: str, body: dict | None = None) -> tuple[int, dict]:
    request = urllib.request.Request(
        env["GATEWAY_URL"].rstrip("/") + path,
        data=json.dumps(body).encode() if body is not None else None,
        headers={"Authorization": f"Bearer {env['GATEWAY_KEY']}", "Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=300) as response:
            return response.status, json.loads(response.read())
    except urllib.error.HTTPError as error:
        return error.code, json.loads(error.read() or b"{}")


def main() -> None:
    env = load_env()
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    if sys.argv[1] == "--usage":
        status, reply = call(env, "/v1/usage")
    else:
        status, reply = call(
            env,
            "/v1/chat",
            {"messages": [{"role": "user", "content": sys.argv[1]}], "role": "manual", "max_tokens": 200},
        )
    print(status)
    print(json.dumps(reply, indent=2))


if __name__ == "__main__":
    main()

"""One-off smoke test: run the starting model on CPU and time two prompts.

Run with:  py -m modal run model-server/smoke_test.py

Runs as an ephemeral app, so nothing stays deployed and billing stops when the
function returns. The function timeout caps the spend if something hangs.
"""

import json
import subprocess
import time
import urllib.error
import urllib.request

import modal

MODEL = "qwen2.5-coder:1.5b"
CPU_CORES = 4  # Modal physical cores (1 core = 2 vCPU)
MEMORY_MIB = 4096
OLLAMA_URL = "http://127.0.0.1:11434"

image = (
    modal.Image.from_registry("ollama/ollama:latest", add_python="3.12")
    .entrypoint([])
    .env({"OLLAMA_MODELS": "/models"})
    # Bake the weights into the image so a cold start does not download them.
    .run_commands(f"ollama serve & sleep 5 && ollama pull {MODEL}")
)

app = modal.App("agentdash-model-smoke-test")

READ_FILE_TOOL = {
    "type": "function",
    "function": {
        "name": "read_file",
        "description": "Read a file from the repository and return its contents.",
        "parameters": {
            "type": "object",
            "properties": {
                "path": {"type": "string", "description": "Path relative to the repo root"}
            },
            "required": ["path"],
        },
    },
}


def _post(path: str, body: dict) -> dict:
    request = urllib.request.Request(
        OLLAMA_URL + path,
        data=json.dumps(body).encode(),
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=240) as response:
            return json.loads(response.read())
    except urllib.error.HTTPError as error:
        return {"error": error.read().decode(errors="replace")}


def _wait_for_server() -> None:
    for _ in range(60):
        try:
            urllib.request.urlopen(OLLAMA_URL + "/api/version", timeout=2)
            return
        except OSError:
            time.sleep(0.5)
    raise RuntimeError("ollama did not start")


def _chat(label: str, messages: list, tools: list | None = None) -> dict:
    body = {
        "model": MODEL,
        "messages": messages,
        "stream": False,
        "options": {"num_predict": 200, "temperature": 0},
    }
    if tools:
        body["tools"] = tools
    started = time.monotonic()
    reply = _post("/api/chat", body)
    wall_seconds = time.monotonic() - started
    if "error" in reply:
        return {"label": label, "error": reply["error"], "wall_seconds": round(wall_seconds, 2)}

    message = reply.get("message", {})
    eval_seconds = reply.get("eval_duration", 0) / 1e9
    prompt_seconds = reply.get("prompt_eval_duration", 0) / 1e9
    return {
        "label": label,
        "wall_seconds": round(wall_seconds, 2),
        "load_seconds": round(reply.get("load_duration", 0) / 1e9, 2),
        "prompt_tokens": reply.get("prompt_eval_count", 0),
        "prompt_tokens_per_second": round(reply.get("prompt_eval_count", 0) / prompt_seconds, 1)
        if prompt_seconds
        else None,
        "output_tokens": reply.get("eval_count", 0),
        "output_tokens_per_second": round(reply.get("eval_count", 0) / eval_seconds, 1)
        if eval_seconds
        else None,
        "content": message.get("content", ""),
        "tool_calls": message.get("tool_calls"),
    }


@app.function(image=image, cpu=CPU_CORES, memory=MEMORY_MIB, timeout=300)
def run_prompts() -> dict:
    container_started = time.monotonic()
    server = subprocess.Popen(["ollama", "serve"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    try:
        _wait_for_server()
        results = [
            _chat(
                "plain",
                [
                    {
                        "role": "user",
                        "content": "Write a Python function that returns the n-th Fibonacci number iteratively. Code only.",
                    }
                ],
            ),
            _chat(
                "tool_call",
                [
                    {
                        "role": "system",
                        "content": "You are a coding agent. Use the provided tools to inspect the repository before answering.",
                    },
                    {"role": "user", "content": "What does the file src/config.ts export?"},
                ],
                tools=[READ_FILE_TOOL],
            ),
        ]
    finally:
        server.terminate()
    return {
        "model": MODEL,
        "cpu_cores": CPU_CORES,
        "memory_mib": MEMORY_MIB,
        "container_seconds": round(time.monotonic() - container_started, 2),
        "results": results,
    }


@app.local_entrypoint()
def main():
    print(json.dumps(run_prompts.remote(), indent=2))

/**
 * Coordinates one run from start to finish: lifecycle, sandbox, clone, agent,
 * patch capture, kill switch, and the record of what the sandbox cost.
 *
 * The router and supervisor are not built yet (steps 6 and 7), so those
 * stages are passed through and say so in the event log.
 */
import { readFile, readdir } from "node:fs/promises";
import { join } from "node:path";

import type { Config } from "../config.ts";
import type { Db } from "../db/index.ts";
import type { Sandbox, SandboxProvider } from "../sandbox-provider/types.ts";
import type { RunStatus } from "./state.ts";
import { signRunToken } from "./tokens.ts";

const REPO_DIR = "/workspace/repo";
const AGENT_DIR = "/agent";
const AGENT_SOURCE = join(import.meta.dirname, "..", "agent");
const KILL_POLL_MS = 1000;

export interface RunDeps {
  db: Db;
  sandboxes: SandboxProvider;
  config: Config;
}

/** Thrown when the owner has asked for the run to stop. */
class Killed extends Error {}
/** Thrown when the gateway refused the agent because the month's budget is spent. */
class BudgetStopped extends Error {}

/** Copies the agent's source files into the sandbox. */
async function installAgent(sandbox: Sandbox): Promise<number> {
  await sandbox.exec(["mkdir", "-p", AGENT_DIR]);
  const files = (await readdir(AGENT_SOURCE)).filter((name) => name.endsWith(".ts"));
  for (const name of files) {
    await sandbox.writeFile(`${AGENT_DIR}/${name}`, await readFile(join(AGENT_SOURCE, name), "utf8"));
  }
  return files.length;
}

export async function executeRun(deps: RunDeps, runId: string): Promise<void> {
  const { db, sandboxes, config } = deps;
  let sandbox: Sandbox | null = null;
  let cloned = false;

  const move = (to: RunStatus, error?: string) => {
    db.setStatus(runId, to, error);
    db.appendEvent(runId, "status", { status: to, ...(error ? { error } : {}) });
  };
  const killRequested = () => db.getRun(runId)?.killRequested === true;
  const checkKill = () => {
    if (killRequested()) throw new Killed();
  };
  const capturePatch = async () => {
    if (!sandbox || !cloned) return;
    // --intent-to-add makes brand-new files show up in the diff as well.
    await sandbox.exec(["git", "add", "--intent-to-add", "."], { workdir: REPO_DIR });
    const diff = await sandbox.exec(["git", "diff"], { workdir: REPO_DIR });
    db.savePatch(runId, diff.stdout);
    db.appendEvent(runId, "patch_captured", { bytes: diff.stdout.length });
  };

  /** Runs the agent in the sandbox, storing its events as they arrive. */
  const runAgent = async (box: Sandbox, task: string): Promise<string> => {
    const expiresAt = Math.floor(Date.now() / 1000) + config.runTokenTtlSeconds;
    let reason = "agent_crashed";
    const agent = box.exec(["node", "--experimental-strip-types", "--no-warnings", `${AGENT_DIR}/main.ts`], {
      workdir: REPO_DIR,
      timeoutSeconds: config.agentTimeoutSeconds,
      env: {
        GATEWAY_URL: config.gatewayUrl,
        // The only credential in the sandbox: valid for this run, briefly, as "worker".
        RUN_PASS: signRunToken(config.gatewayKey, runId, expiresAt),
        TASK: task,
        REPO_DIR,
        MAX_STEPS: String(config.agentMaxSteps),
      },
      onStdoutLine: (line) => {
        try {
          const { type, ...data } = JSON.parse(line) as { type: string; reason?: string };
          if (type === "finished" && data.reason) reason = data.reason;
          db.appendEvent(runId, `agent_${type}`, data);
        } catch {
          if (line.trim()) db.appendEvent(runId, "agent_output", { line: line.slice(0, 500) });
        }
      },
    });
    // A kill must not wait for the agent's current step, so watch for it alongside.
    let watching = true;
    const killed = (async () => {
      while (watching) {
        if (killRequested()) throw new Killed();
        await new Promise((resolve) => setTimeout(resolve, KILL_POLL_MS));
      }
    })();
    try {
      const result = await Promise.race([agent, killed.then(() => null)]);
      if (result?.timedOut) reason = "timeout";
      else if (result && result.exitCode !== 0 && reason === "agent_crashed") {
        db.appendEvent(runId, "agent_output", { stderr: result.stderr.slice(-500) });
      }
    } finally {
      watching = false;
      agent.catch(() => {}); // if killed, the sandbox is destroyed underneath it
    }
    return reason;
  };

  try {
    const run = db.getRun(runId);
    if (!run) throw new Error(`No run ${runId}`);

    move("triaging");
    const assignment = { tier: "small", decidedBy: "default", reason: "Router not built yet (step 6)." };
    db.addAssignment(runId, assignment);
    db.appendEvent(runId, "routing", assignment);
    checkKill();

    move("running");
    const createStarted = Date.now();
    sandbox = await sandboxes.create({ runId, maxLifetimeSeconds: config.sandboxMaxLifetimeSeconds });
    db.appendEvent(runId, "sandbox_created", {
      sandboxId: sandbox.id,
      seconds: (Date.now() - createStarted) / 1000,
    });
    checkKill();

    const clone = await sandbox.exec(["git", "clone", "--depth", "1", run.repoUrl, REPO_DIR], {
      timeoutSeconds: 120,
    });
    db.appendEvent(runId, "command", {
      command: `git clone --depth 1 ${run.repoUrl}`,
      exitCode: clone.exitCode,
      seconds: clone.seconds,
      stderr: clone.stderr.slice(-500),
    });
    if (clone.exitCode !== 0) throw new Error(`Could not clone ${run.repoUrl}`);
    cloned = true;
    checkKill();

    db.appendEvent(runId, "agent_installed", { files: await installAgent(sandbox) });
    const reason = await runAgent(sandbox, run.task);
    await capturePatch();
    if (reason === "budget_exhausted") throw new BudgetStopped();
    if (reason !== "finished") throw new Error(`The agent stopped without finishing: ${reason}`);

    move("reviewing");
    db.appendEvent(runId, "review_skipped", { reason: "Supervisor not built yet (step 7)." });
    move("done");
  } catch (error) {
    if (error instanceof Killed) {
      // Decision 18: a killed run keeps whatever work exists so far.
      await capturePatch().catch(() => {});
      move("killed");
    } else if (error instanceof BudgetStopped) {
      move("budget_stopped");
    } else {
      move("failed", error instanceof Error ? error.message : String(error));
    }
  } finally {
    if (sandbox) {
      const report = await sandbox.destroy();
      db.saveSandboxUsage(runId, report.lifetimeSeconds, report.estimatedCostUsd);
      db.appendEvent(runId, "sandbox_destroyed", { ...report });
    }
  }
}

/** The run lifecycle. Pure rules, no I/O. */

export const STATUSES = [
  "queued",
  "triaging",
  "running",
  "reviewing",
  "done",
  "failed",
  "killed",
  "budget_stopped",
] as const;

export type RunStatus = (typeof STATUSES)[number];

const HAPPY_PATH: Partial<Record<RunStatus, RunStatus>> = {
  queued: "triaging",
  triaging: "running",
  running: "reviewing",
  reviewing: "done",
};

/** Ways a run can end early, from any state that is still in progress. */
const EARLY_ENDS: RunStatus[] = ["failed", "killed", "budget_stopped"];

export function isTerminal(status: RunStatus): boolean {
  return !(status in HAPPY_PATH);
}

export function canTransition(from: RunStatus, to: RunStatus): boolean {
  if (isTerminal(from)) return false;
  return HAPPY_PATH[from] === to || EARLY_ENDS.includes(to);
}

export function assertTransition(from: RunStatus, to: RunStatus): void {
  if (!canTransition(from, to)) throw new Error(`A run cannot go from ${from} to ${to}`);
}

/**
 * Per-run passes for the gateway.
 *
 * A pass is "<runId>.<expiry>.<signature>". The orchestrator signs it with the
 * gateway key; the gateway checks the signature and expiry without needing a
 * database. A sandbox holds only this, never the key itself.
 * gateway/core.py implements the same format and must stay in step.
 */
import { createHmac, timingSafeEqual } from "node:crypto";

function signature(secret: string, payload: string): string {
  return createHmac("sha256", secret).update(payload).digest("hex");
}

export function signRunToken(secret: string, runId: string, expiresAt: number): string {
  const payload = `${runId}.${Math.floor(expiresAt)}`;
  return `${payload}.${signature(secret, payload)}`;
}

/** The run id if the pass is genuine and unexpired, otherwise null. */
export function verifyRunToken(secret: string, token: string, now: number): string | null {
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  const [runId, expiry, given] = parts;
  const expected = signature(secret, `${runId}.${expiry}`);
  if (given.length !== expected.length) return null;
  if (!timingSafeEqual(Buffer.from(given), Buffer.from(expected))) return null;
  if (!/^\d+$/.test(expiry) || now >= Number(expiry)) return null;
  return runId;
}

/**
 * Live check: start the API, send real runs through it, and print what
 * happened. Each run uses a sandbox and wakes the model, so the whole check
 * costs a cent or two.
 *
 *   node orchestrator/try-it.ts              the default tasks below
 *   node orchestrator/try-it.ts "<task>"     one task of your own
 */
import { writeFile } from "node:fs/promises";
import type { AddressInfo } from "node:net";

import { createApi } from "../api/server.ts";
import { loadConfig } from "../config.ts";
import { Db } from "../db/index.ts";
import { ModalSandboxProvider } from "../sandbox-provider/modal.ts";
import { executeRun } from "./run.ts";
import { isTerminal } from "./state.ts";

const REPO = "https://github.com/octocat/Hello-World";
const DEFAULT_TASKS = [
  "Create a file named HELLO.md containing exactly this text: Hello from AgentDash.",
  "Add this line to the end of the file named README: Edited by an agent.",
  "Create a file named count.sh that prints the numbers 1 to 3, one per line, then run it with sh to check it works.",
];

process.loadEnvFile(".env");
const config = loadConfig();
const db = new Db(":memory:");
const sandboxes = new ModalSandboxProvider();
const api = createApi({
  db,
  ownerToken: config.ownerToken,
  startRun: (runId) => void executeRun({ db, sandboxes, config }, runId),
});
await new Promise<void>((resolve) => api.listen(0, resolve));
const base = `http://localhost:${(api.address() as AddressInfo).port}`;
const owner = { authorization: `Bearer ${config.ownerToken}`, "content-type": "application/json" };

async function runToEnd(task: string, killAfterMs?: number) {
  const started = Date.now();
  const created = await fetch(`${base}/runs`, { method: "POST", headers: owner, body: JSON.stringify({ task, repoUrl: REPO }) });
  const { run } = (await created.json()) as { run: { id: string } };
  if (killAfterMs !== undefined) {
    await new Promise((resolve) => setTimeout(resolve, killAfterMs));
    await fetch(`${base}/runs/${run.id}/kill`, { method: "POST", headers: owner });
  }
  for (;;) {
    const state = (await (await fetch(`${base}/runs/${run.id}`)).json()) as { run: any };
    if (isTerminal(state.run.status) && state.run.sandboxSeconds !== null) {
      const { events } = (await (await fetch(`${base}/runs/${run.id}/events`)).json()) as { events: any[] };
      const model = events.filter((event) => event.type === "agent_model").map((event) => event.data.usage ?? {});
      const sum = (key: string) => Number(model.reduce((total, usage) => total + (usage[key] ?? 0), 0).toFixed(4));
      return {
        task,
        status: state.run.status,
        error: state.run.error,
        wallSeconds: (Date.now() - started) / 1000,
        sandboxSeconds: state.run.sandboxSeconds,
        sandboxCostUsd: state.run.sandboxCostUsd,
        modelCalls: model.length,
        modelSeconds: sum("model_seconds"),
        promptTokens: sum("prompt_tokens"),
        outputTokens: sum("output_tokens"),
        modelCostUsd: sum("cost_usd"),
        parseErrors: events.filter((event) => event.type === "agent_parse_error").length,
        steps: events
          .filter((event) => ["agent_tool_call", "agent_tool_result", "agent_parse_error", "agent_finished", "agent_output"].includes(event.type))
          .map((event) => `${event.type.replace("agent_", "")} ${JSON.stringify(event.data)}`.slice(0, 260)),
        patch: state.run.patch,
      };
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
}

// --export <file> saves the complete runs (record, model choices, every event)
// for the dashboard's recorded-run preview, and skips the kill check.
const exportAt = process.argv.indexOf("--export");
const exportPath = exportAt === -1 ? null : process.argv[exportAt + 1];
const custom = exportAt === 2 ? undefined : process.argv[2];
const results = [];
for (const task of custom ? [custom] : DEFAULT_TASKS) results.push(await runToEnd(task));
if (!custom && !exportPath) results.push({ killed: await runToEnd(DEFAULT_TASKS[2], 6000) });

if (exportPath) {
  const usage = await fetch(`${config.gatewayUrl}/v1/usage`, { headers: { authorization: `Bearer ${config.gatewayKey}` } });
  const { budget } = (await usage.json()) as { budget: unknown };
  const runs = db
    .listRuns()
    .reverse()
    .map((run) => ({ run, assignments: db.listAssignments(run.id), events: db.listEvents(run.id) }));
  await writeFile(exportPath, JSON.stringify({ exportedAt: new Date().toISOString(), budget, runs }, null, 1));
}

console.log(JSON.stringify(results.map(({ patch, ...rest }: any) => rest), null, 2));
api.close();
db.close();
sandboxes.close();

