test("the happy path is queued → triaging → running → reviewing → done", () => {
  const path = ["queued", "triaging", "running", "reviewing", "done"] as const;
  for (let i = 0; i < path.length - 1; i++) assert.ok(canTransition(path[i], path[i + 1]));
});

