// The Pseudocode tab: a folder tree of the repository, and for the chosen file
// its plain-language pseudocode beside the real code. Clicking a pseudocode
// chunk highlights the lines it describes. Everything comes from
// data/code.json, built by tools/build-pseudocode.ts; nothing else is loaded.

(() => {
  const FIRST_FILE = "agent/loop.ts";
  const tree = document.getElementById("code-tree");
  const detail = document.getElementById("code-detail");
  const LEVELS = [
    ["overview", "High-level explanation"],
    ["detail", "Detailed pseudocode"],
  ];
  // Shown above the detailed pseudocode, for readers who do not program.
  const WORDS = [
    ["CALLED BY / TAKES / RETURNS", "which code runs a function, the values it is given (and where they come from), and the result it gives back."],
    ["Type, interface", "a description of the form some data must have. It is checked while the code is written and does nothing when the code runs."],
    ["Object", "a bundle of named values, written { name: value }. An array is an ordered list, written [a, b]."],
    ["String", "a piece of text."],
    ["Promise, await", "a promise is a result that will arrive later, such as a network reply. await pauses the function until it does."],
    ["Throw, try, catch", "code that fails throws an error. Wrapping code in try lets a catch block receive the error instead of the program stopping."],
    ["Export", "makes a function or value usable from other files. Without it, only this file can use it."],
  ];
  let files = null;
  let current = null;
  // "overview" explains each part of a file; "detail" is the function-by-function plan.
  let level = "overview";
  /** The chunks on screen: the current file's, at the current level. */
  let shown = [];

  function make(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  // ---------------------------------------------------------------- tree

  /** Turns the flat list of paths into nested folders. */
  function nest(paths) {
    const root = { folders: new Map(), files: [] };
    for (const path of paths) {
      const parts = path.split("/");
      let folder = root;
      for (const part of parts.slice(0, -1)) {
        if (!folder.folders.has(part)) folder.folders.set(part, { folders: new Map(), files: [] });
        folder = folder.folders.get(part);
      }
      folder.files.push(path);
    }
    return root;
  }

  function drawFolder(folder) {
    const list = make("ul");
    for (const [name, child] of [...folder.folders].sort(([a], [b]) => a.localeCompare(b))) {
      const item = make("li");
      const fold = make("details");
      fold.append(make("summary", "", `${name}/`), drawFolder(child));
      item.append(fold);
      list.append(item);
    }
    for (const path of folder.files) {
      const item = make("li");
      const button = make("button", "file", path.split("/").pop());
      button.type = "button";
      if (!files.find((entry) => entry.path === path).chunks.length) button.classList.add("bare");
      button.dataset.path = path;
      button.addEventListener("click", () => showFile(path, true));
      item.append(button);
      list.append(item);
    }
    return list;
  }

  // ---------------------------------------------------------------- one file

  function showFile(path, scroll) {
    const file = files.find((entry) => entry.path === path);
    if (!file) return;
    current = file;
    shown = level === "detail" ? file.detail : file.chunks;
    for (const button of tree.querySelectorAll("button.file")) {
      button.setAttribute("aria-current", String(button.dataset.path === path));
    }

    const lines = file.text.replace(/\n$/, "").split("\n");
    const code = make("div", "code-pane");
    const inner = make("div", "code-lines");
    lines.forEach((text, index) => {
      const row = make("div", "line");
      row.dataset.n = index + 1;
      row.append(make("span", "n", String(index + 1)), make("span", "t", text || " "));
      inner.append(row);
    });
    code.append(inner);
    // Clicking a line of code selects the chunk that explains it.
    inner.addEventListener("click", (event) => {
      const row = event.target.closest(".line");
      if (!row) return;
      const n = Number(row.dataset.n);
      const index = shown.findIndex((chunk) => chunk.ranges.some(([from, to]) => n >= from && n <= to));
      if (index !== -1) selectChunk(index, false);
    });

    const pseudo = make("div", "pseudo-pane");
    // The detailed level opens with the plan: what the file needs and how its parts connect.
    if (level === "detail" && shown.length) {
      const words = make("details", "words");
      const list = make("dl");
      for (const [term, meaning] of WORDS) list.append(make("dt", "", term), make("dd", "", meaning));
      words.append(make("summary", "", "Words used in this pseudocode"), list);
      pseudo.append(words);
    }
    if (level === "detail" && file.plan) pseudo.append(make("div", "plan", file.plan));
    shown.forEach((chunk, index) => {
      // Not a real button: text inside a button cannot be selected and copied.
      const card = make("div", "chunk");
      card.setAttribute("role", "button");
      card.tabIndex = 0;
      card.setAttribute("aria-pressed", "false");
      const where = chunk.ranges.map(([from, to]) => (from === to ? `${from}` : `${from}–${to}`)).join(", ");
      card.append(make("span", "chunk-title", chunk.title), make("span", "chunk-lines", `lines ${where}`), make("span", "chunk-text", chunk.text));
      card.addEventListener("click", () => {
        // Dragging to select text ends in a click too; leave the selection alone.
        if (!String(window.getSelection()).trim()) selectChunk(index, true);
      });
      card.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          selectChunk(index, true);
        }
      });
      pseudo.append(card);
    });

    if (!shown.length) pseudo.append(make("p", "note", "No pseudocode has been written for this file yet."));

    const head = make("div", "code-head");
    const switcher = make("div", "level-switch");
    switcher.setAttribute("role", "group");
    switcher.setAttribute("aria-label", "Level of detail");
    for (const [value, label] of LEVELS) {
      const button = make("button", "", label);
      button.type = "button";
      button.setAttribute("aria-pressed", String(value === level));
      button.addEventListener("click", () => {
        if (value === level) return;
        level = value;
        showFile(path, false);
      });
      switcher.append(button);
    }
    head.append(make("h2", "", path), make("p", "", file.summary), switcher);

    const copy = make("button", "copy", "Copy all");
    copy.type = "button";
    copy.hidden = !shown.length;
    copy.addEventListener("click", async () => {
      const parts = shown.map((chunk) => `${chunk.title}\n${chunk.text}`);
      if (level === "detail" && file.plan) parts.unshift(file.plan);
      try {
        await navigator.clipboard.writeText(`${path}\n\n${parts.join("\n\n")}\n`);
        copy.textContent = "Copied";
      } catch {
        copy.textContent = "Copy failed: select the text instead";
      }
      setTimeout(() => (copy.textContent = "Copy all"), 2000);
    });
    const title = make("h3", "", level === "detail" ? "Detailed pseudocode" : "High-level explanation");
    title.append(copy);

    const columns = make("div", "code-columns");
    const left = make("div");
    const right = make("div");
    left.append(title, pseudo);
    right.append(make("h3", "", `Actual code · ${lines.length} lines`), code);
    columns.append(left, right);
    detail.replaceChildren(head, columns);
    if (scroll) detail.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  function selectChunk(index, scrollCode) {
    const chunk = shown[index];
    const cards = detail.querySelectorAll(".chunk");
    cards.forEach((card, at) => card.setAttribute("aria-pressed", String(at === index)));
    const pane = detail.querySelector(".code-pane");
    let first = null;
    for (const row of pane.querySelectorAll(".line")) {
      const n = Number(row.dataset.n);
      const lit = chunk.ranges.some(([from, to]) => n >= from && n <= to);
      row.classList.toggle("lit", lit);
      if (lit && !first) first = row;
    }
    // Scroll only the pane that was not clicked, and never the page itself.
    if (scrollCode && first) {
      pane.scrollTo({ top: first.offsetTop - 40, behavior: "smooth" });
    } else if (!scrollCode) {
      const list = detail.querySelector(".pseudo-pane");
      list.scrollTo({ top: cards[index].offsetTop - 12, behavior: "smooth" });
    }
  }

  // ---------------------------------------------------------------- loading

  // The data is sizeable, so it is fetched the first time the tab is opened.
  document.addEventListener("tabshown", async (event) => {
    if (event.detail !== "pseudocode" || files) return;
    files = [];
    try {
      const response = await fetch("data/code.json");
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      files = (await response.json()).files;
    } catch (error) {
      files = null;
      tree.replaceChildren(make("p", "note", `Could not load the repository view (${error.message}).`));
      return;
    }
    tree.replaceChildren(drawFolder(nest(files.map((file) => file.path))));
    showFile(files.some((file) => file.path === FIRST_FILE) ? FIRST_FILE : files[0].path, false);
  });
})();

:root {
  --bg: #f6f7f9;
  --surface: #ffffff;
  --text: #1b1f24;
  --muted: #5b6470;
  --border: #d5dae1;
  --accent: #0b6bcb;
  --accent-soft: #e3effb;
  --built: #1a7f4b;
  --built-soft: #e2f4ea;
  --later: #8a929d;
  --code-bg: #eef0f3;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #14171b;
    --surface: #1c2026;
    --text: #e6e9ed;
    --muted: #9aa3ae;
    --border: #343a43;
    --accent: #6cb2f5;
    --accent-soft: #1b3350;
    --built: #5fcf94;
    --built-soft: #183526;
    --later: #747c87;
    --code-bg: #262b32;
  }
}
:root[data-theme="dark"] {
  --bg: #14171b;
  --surface: #1c2026;
  --text: #e6e9ed;
  --muted: #9aa3ae;
  --border: #343a43;
  --accent: #6cb2f5;
  --accent-soft: #1b3350;
  --built: #5fcf94;
  --built-soft: #183526;
  --later: #747c87;
  --code-bg: #262b32;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
main { max-width: 980px; margin: 0 auto; padding: 32px 16px 64px; }
h1 { font-size: 1.7rem; margin: 0 0 4px; }
h2 { font-size: 1.05rem; margin: 28px 0 8px; }
p { margin: 0 0 12px; }
.lede { color: var(--muted); margin-bottom: 24px; }
code {
  background: var(--code-bg);
  padding: 1px 5px;
  border-radius: 4px;
  font: 0.88em ui-monospace, "Cascadia Code", Consolas, monospace;
}
pre {
  background: var(--code-bg);
  padding: 12px 14px;
  border-radius: 8px;
  overflow-x: auto;
  font: 0.86rem/1.5 ui-monospace, "Cascadia Code", Consolas, monospace;
  margin: 0 0 12px;
}

details.step {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 10px;
  margin-bottom: 10px;
}
details.step > summary {
  cursor: pointer;
  padding: 14px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  font-weight: 600;
  list-style: none;
}
details.step > summary::-webkit-details-marker { display: none; }
details.step > summary::before {
  content: "▸";
  color: var(--muted);
  transition: transform 0.15s;
}
details.step[open] > summary::before { transform: rotate(90deg); }
details.step > summary .num { color: var(--muted); font-weight: 500; }
.body { padding: 0 16px 18px; border-top: 1px solid var(--border); }

.chip {
  margin-left: auto;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 9px;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--muted);
  white-space: nowrap;
}
.chip.done { color: var(--built); background: var(--built-soft); border-color: transparent; }
.chip.current { color: var(--accent); background: var(--accent-soft); border-color: transparent; }

.scroll { overflow-x: auto; }
svg.diagram { display: block; min-width: 720px; width: 100%; height: auto; }
.diagram text { fill: var(--text); font: 13px system-ui, -apple-system, "Segoe UI", sans-serif; }
.diagram .t-title { font-weight: 600; }
.diagram .t-muted { fill: var(--muted); font-size: 12px; }
.diagram .box-built { fill: var(--built-soft); stroke: var(--built); stroke-width: 1.5; }
.diagram .box-todo { fill: var(--accent-soft); stroke: var(--accent); stroke-width: 1.5; }
.diagram .box-later { fill: none; stroke: var(--later); stroke-width: 1.2; stroke-dasharray: 5 4; }
.diagram .zone { fill: none; stroke: var(--border); stroke-width: 1.5; }
.diagram .arrow { stroke: var(--text); stroke-width: 1.4; fill: none; }
.diagram .arrow-later { stroke: var(--later); stroke-width: 1.2; fill: none; stroke-dasharray: 5 4; }
.diagram .head { fill: var(--text); }
.diagram .head-later { fill: var(--later); }

.legend { display: flex; gap: 18px; flex-wrap: wrap; font-size: 0.85rem; color: var(--muted); margin: 8px 0 0; }
.legend span::before {
  content: "";
  display: inline-block;
  width: 14px; height: 14px;
  border-radius: 3px;
  margin-right: 6px;
  vertical-align: -2px;
}
.legend .l-built::before { background: var(--built-soft); border: 1.5px solid var(--built); }
.legend .l-todo::before { background: var(--accent-soft); border: 1.5px solid var(--accent); }
.legend .l-later::before { border: 1.5px dashed var(--later); }

dl.qa dt { font-weight: 600; margin-top: 12px; }
dl.qa dd { margin: 2px 0 0; color: var(--text); }

table { border-collapse: collapse; width: 100%; font-size: 0.92rem; min-width: 620px; }
th, td { text-align: left; vertical-align: top; padding: 8px 10px; border-bottom: 1px solid var(--border); }
th { color: var(--muted); font-weight: 600; font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.03em; }
td:first-child { white-space: nowrap; }
ul { margin: 0 0 12px; padding-left: 20px; }
li { margin-bottom: 4px; }
.note { color: var(--muted); font-size: 0.9rem; }

nav.tabs { display: flex; gap: 4px; margin: 0 0 24px; border-bottom: 1px solid var(--border); }
nav.tabs a {
  padding: 8px 14px;
  color: var(--muted);
  text-decoration: none;
  font-weight: 600;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
}
nav.tabs a:hover { color: var(--text); }
nav.tabs a[aria-current="page"] { color: var(--accent); border-bottom-color: var(--accent); }
h3 { font-size: 0.98rem; margin: 22px 0 6px; }
td.num, th.num { text-align: right; font-variant-numeric: tabular-nums; }
a { color: var(--accent); }
.good { color: var(--built); font-weight: 600; }
.bad { color: #c0392b; font-weight: 600; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) .bad { color: #ff8a7a; } }
:root[data-theme="dark"] .bad { color: #ff8a7a; }

/* ---- single-page tabs */
section[hidden] { display: none; }

/* ---- research topics inside a date */
details.topic { border: 1px solid var(--border); border-radius: 8px; margin: 10px 0; }
details.topic > summary { cursor: pointer; padding: 10px 14px; font-weight: 600; }
details.topic[open] > summary { border-bottom: 1px solid var(--border); }
.topic-body { padding: 4px 14px 12px; }

/* ---- dashboard preview */
.tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 10px; margin-bottom: 24px; }
.tile { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 14px 16px; }
.tile-label { color: var(--muted); font-size: 0.8rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.03em; }
.tile-value { font-size: 1.7rem; font-weight: 650; font-variant-numeric: tabular-nums; margin: 2px 0; }
.tile-note { color: var(--muted); font-size: 0.85rem; }
.meter { height: 6px; background: var(--code-bg); border-radius: 3px; margin-top: 8px; overflow: hidden; }
.meter-fill { height: 100%; background: var(--accent); border-radius: 3px; }

.dash { display: grid; grid-template-columns: minmax(0, 300px) minmax(0, 1fr); gap: 20px; align-items: start; }
@media (max-width: 760px) { .dash { grid-template-columns: minmax(0, 1fr); } }
.dash h2 { margin-top: 0; }
.run-list { list-style: none; margin: 0 0 12px; padding: 0; }
.run-list li { margin: 0 0 8px; }
.run-row {
  display: grid; gap: 4px; width: 100%; text-align: left; font: inherit; color: inherit; cursor: pointer;
  background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 10px 12px;
}
.run-row[aria-current] { border-color: var(--accent); box-shadow: inset 3px 0 0 var(--accent); }
.run-task { font-size: 0.92rem; }
.run-meta { color: var(--muted); font-size: 0.8rem; font-variant-numeric: tabular-nums; }
.run-detail { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 16px; min-width: 0; }
.run-head { display: flex; gap: 10px; align-items: baseline; flex-wrap: wrap; }
.run-head h3 { margin: 0; font-size: 1.05rem; }
.run-detail .note { overflow-wrap: anywhere; }

.status { font-size: 0.75rem; font-weight: 700; padding: 2px 9px; border-radius: 999px; white-space: nowrap; justify-self: start; border: 1px solid var(--border); color: var(--muted); }
.status.good { color: var(--built); background: var(--built-soft); border-color: transparent; }
.status.bad { color: #c0392b; border-color: currentColor; }

.controls { display: flex; gap: 8px; flex-wrap: wrap; margin: 12px 0 4px; }
.button { font: inherit; font-size: 0.88rem; font-weight: 600; padding: 6px 12px; border-radius: 8px; border: 1px solid var(--border); background: var(--bg); color: var(--text); cursor: pointer; }
.button:hover:not([disabled]) { border-color: var(--accent); color: var(--accent); }
.button[disabled] { opacity: 0.5; cursor: not-allowed; }

.feed { list-style: none; margin: 0; padding: 0; }
.feed-item { display: grid; grid-template-columns: 52px 78px minmax(0, 1fr); gap: 8px; padding: 7px 0; border-bottom: 1px solid var(--border); font-size: 0.9rem; }
.feed-item[hidden] { display: none; }
.feed-time { color: var(--muted); font-variant-numeric: tabular-nums; font-size: 0.8rem; padding-top: 2px; }
.feed-who { font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); padding-top: 3px; }
.who-agent .feed-who, .who-model .feed-who { color: var(--accent); }
.feed-title { font-weight: 600; overflow-wrap: anywhere; }
.feed-body pre { margin: 6px 0 0; white-space: pre-wrap; overflow-wrap: anywhere; }
.feed-body .note { margin: 2px 0 0; }

.diff { white-space: pre-wrap; overflow-wrap: anywhere; }
.diff .add { color: var(--built); }
.diff .del { color: #c0392b; }
table.cost { min-width: 0; }
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .status.bad, :root:not([data-theme="light"]) .diff .del { color: #ff8a7a; }
}
:root[data-theme="dark"] .status.bad, :root[data-theme="dark"] .diff .del { color: #ff8a7a; }

/* ---- pseudocode tab */
main[data-tab="pseudocode"] { max-width: 1500px; }
.code-tree { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 10px 14px; margin-bottom: 8px; }
.code-tree ul { list-style: none; margin: 0; padding-left: 18px; }
.code-tree > ul { padding-left: 0; }
.code-tree li { margin: 0; }
.code-tree summary { cursor: pointer; padding: 2px 0; font-weight: 600; }
.code-tree button.file {
  background: none; border: 0; padding: 2px 6px; margin-left: 12px; border-radius: 4px; cursor: pointer;
  color: var(--text); font: 0.9rem ui-monospace, "Cascadia Code", Consolas, monospace;
}
.code-tree button.file:hover { background: var(--code-bg); }
.code-tree button.file[aria-current="true"] { background: var(--accent-soft); color: var(--accent); font-weight: 600; }
.code-detail { scroll-margin-top: 8px; }
.code-head h2 { font: 600 1.05rem ui-monospace, "Cascadia Code", Consolas, monospace; margin-top: 20px; }
.code-columns { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 16px; }
.code-columns h3 { margin-top: 8px; color: var(--muted); font-size: 0.8rem; text-transform: uppercase; letter-spacing: 0.03em; }
.pseudo-pane, .code-pane { height: calc(100vh - 90px); min-height: 320px; overflow: auto; border: 1px solid var(--border); border-radius: 10px; background: var(--surface); }
.pseudo-pane { position: relative; padding: 8px; }
.chunk {
  display: block; width: 100%; text-align: left; cursor: pointer; margin-bottom: 8px; padding: 10px 12px;
  background: var(--bg); color: var(--text); border: 1px solid var(--border); border-left: 4px solid var(--border); border-radius: 8px; font: inherit;
}
.chunk:hover { border-left-color: var(--accent); }
.chunk[aria-pressed="true"] { background: var(--accent-soft); border-color: var(--accent); }
.chunk-title { display: block; font-weight: 600; }
.chunk-lines { display: block; color: var(--muted); font-size: 0.78rem; margin-bottom: 6px; }
.chunk-text { display: block; white-space: pre-wrap; font: 0.84rem/1.5 ui-monospace, "Cascadia Code", Consolas, monospace; }
.code-pane { position: relative; font: 0.8rem/1.5 ui-monospace, "Cascadia Code", Consolas, monospace; }
.code-lines { min-width: max-content; padding: 6px 0; }
.line { display: flex; cursor: pointer; }
.line .n { flex: none; width: 3.6em; padding-right: 12px; text-align: right; color: var(--later); user-select: none; }
.line .t { white-space: pre; padding-right: 16px; }
.line.lit { background: var(--accent-soft); box-shadow: inset 4px 0 0 var(--accent); }
@media (max-width: 900px) {
  .code-columns { grid-template-columns: minmax(0, 1fr); }
  .pseudo-pane, .code-pane { height: 60vh; }
}
.code-tree button.file.bare { color: var(--later); }
.level-switch { display: inline-flex; margin: 4px 0 6px; border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.level-switch button { background: var(--surface); color: var(--muted); border: 0; padding: 7px 14px; font: inherit; font-size: 0.92rem; cursor: pointer; }
.level-switch button + button { border-left: 1px solid var(--border); }
.level-switch button[aria-pressed="true"] { background: var(--accent); color: #fff; font-weight: 600; }
.plan { white-space: pre-wrap; margin-bottom: 8px; padding: 10px 12px; border: 1px dashed var(--border); border-radius: 8px; font: 0.84rem/1.5 ui-monospace, "Cascadia Code", Consolas, monospace; }
.chunk { box-sizing: border-box; user-select: text; }
.chunk:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
.plan { user-select: text; }
.code-columns h3 { display: flex; align-items: center; justify-content: space-between; min-height: 26px; }
button.copy { background: var(--surface); color: var(--muted); border: 1px solid var(--border); border-radius: 6px; padding: 2px 10px; font: inherit; font-size: 0.78rem; text-transform: none; letter-spacing: 0; cursor: pointer; }
button.copy:hover { color: var(--accent); border-color: var(--accent); }
details.words { margin-bottom: 8px; padding: 8px 12px; border: 1px solid var(--border); border-radius: 8px; font-size: 0.88rem; }
details.words summary { cursor: pointer; font-weight: 600; }
details.words dl { margin: 8px 0 0; }
details.words dt { font-weight: 600; margin-top: 6px; }
details.words dd { margin: 0; color: var(--muted); }
